import crypto from "node:crypto";

/**
 * Vercel Serverless Function: Verify Email Token
 * Verifies the HMAC-SHA256 signature generated by /api/send-email (type: "email_verification")
 * and activates the matching account in Supabase `public.accounts`.
 */

const DEFAULT_SUPABASE_URL = "https://pbbtiazbpolvajjsqirs.supabase.co";
const DEFAULT_SUPABASE_ANON_KEY =
  "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InBiYnRpYXpicG9sdmFqanNxaXJzIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzQ1NDExMDMsImV4cCI6MjA5MDExNzEwM30.t_X04dY_s_58n-uK_cQ6xS5J5g6N3hX4vX-yQ_vX3n4";

function signVerificationToken(email, exp, secret) {
  return crypto
    .createHmac("sha256", secret)
    .update(`${email}|${exp}`)
    .digest("hex");
}

function safeHexEqual(a, b) {
  if (typeof a !== "string" || typeof b !== "string") return false;
  if (a.length !== b.length || a.length === 0) return false;
  try {
    return crypto.timingSafeEqual(Buffer.from(a, "hex"), Buffer.from(b, "hex"));
  } catch {
    return false;
  }
}

export default async function handler(req, res) {
  res.setHeader("Access-Control-Allow-Credentials", "true");
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Methods", "GET,OPTIONS,POST");
  res.setHeader(
    "Access-Control-Allow-Headers",
    "X-CSRF-Token, X-Requested-With, Accept, Accept-Version, Content-Length, Content-MD5, Content-Type, Date, X-Api-Version, Authorization"
  );

  if (req.method === "OPTIONS") return res.status(200).end();
  if (req.method !== "POST" && req.method !== "GET") {
    return res.status(405).json({ ok: false, message: "Method not allowed" });
  }

  try {
    const body =
      req.method === "POST"
        ? typeof req.body === "string"
          ? JSON.parse(req.body)
          : req.body || {}
        : req.query || {};

    const cleanEmail = String(body.email || "").trim().toLowerCase();
    const expNum = Number(body.exp);
    const sig = String(body.sig || "").trim().toLowerCase();

    if (!cleanEmail || !expNum || !sig) {
      return res.status(400).json({ ok: false, message: "Invalid verification link." });
    }

    if (Date.now() > expNum) {
      return res.status(400).json({
        ok: false,
        expired: true,
        message: "This verification link has expired. Please request a new one.",
      });
    }

    const secret = (process.env.VERIFY_SECRET || process.env.RESEND_API_KEY || "").trim();
    if (!secret) {
      return res.status(500).json({
        ok: false,
        message: "Verification secret is not configured on the server.",
      });
    }

    const expectedSig = signVerificationToken(cleanEmail, expNum, secret);
    if (!safeHexEqual(sig, expectedSig)) {
      return res.status(400).json({
        ok: false,
        message: "Invalid or tampered verification link.",
      });
    }

    const supabaseUrl = (
      process.env.SUPABASE_URL ||
      process.env.VITE_SUPABASE_URL ||
      DEFAULT_SUPABASE_URL
    ).replace(/\/+$/, "");
    const supabaseKey = (
      process.env.SUPABASE_SERVICE_ROLE_KEY ||
      process.env.SUPABASE_ANON_KEY ||
      process.env.VITE_SUPABASE_ANON_KEY ||
      DEFAULT_SUPABASE_ANON_KEY
    ).trim();

    const patchRes = await fetch(
      `${supabaseUrl}/rest/v1/accounts?email=eq.${encodeURIComponent(cleanEmail)}`,
      {
        method: "PATCH",
        headers: {
          apikey: supabaseKey,
          Authorization: `Bearer ${supabaseKey}`,
          "Content-Type": "application/json",
          Prefer: "return=representation",
        },
        body: JSON.stringify({ status: "active" }),
      }
    );

    if (!patchRes.ok) {
      const errText = await patchRes.text().catch(() => "");
      console.warn("Supabase verify patch warning:", patchRes.status, errText);
    }

    return res.status(200).json({ ok: true, email: cleanEmail });
  } catch (err) {
    return res.status(500).json({
      ok: false,
      message: err?.message || "Failed to verify email address.",
    });
  }
}
